// Phrases that mean "AI was used to make this". Matched against normalized text
// (see core/text.ts). Precision first: a bare "AI" never counts, because digital
// downloads routinely list "AI" files (Adobe Illustrator), and names like "Firefly",
// "Leonardo", or "prompt" only count with AI context.

const AI = String.raw`(?:ai|artificial intelligence)`;
const END = String.raw`(?![\w])`;

export const DISCLOSURE_PATTERNS: readonly RegExp[] = [
  // "ai generated", "ai-generated"
  /\bai[\s-]?generated\b/g,
  // "generated by/with/using ai"
  new RegExp(String.raw`\bgenerated\s+(?:by|with|using|via|through)\s+(?:an?\s+)?${AI}${END}`, "g"),
  // "ai art", "ai artwork", "ai artist", "ai portrait", "ai wall art", ...
  /\bai[\s-]?(?:art|artworks?|artists?|paintings?|illustrations?|portraits?|prints?|wall art|pictures?|photos?|photography|drawings?|creations?)\b/g,
  // "ai-assisted"
  /\bai[\s-]assisted\b/g,
  // "created with ai", "made using ai", "creation by artificial intelligence", ...
  new RegExp(
    String.raw`\b(?:created|made|designed|produced|rendered|crafted|creations?)\s+(?:(?:entirely|partly|partially|fully|completely|digitally)\s+)?(?:with|using|by|via|through)\s+(?:the\s+help\s+of\s+)?(?:an?\s+)?${AI}${END}`,
    "g",
  ),
  // "ai software", "ai tools", "ai image generator", ...
  new RegExp(
    String.raw`\b${AI}\s+(?:software|tools?|(?:image\s+)?generators?|programs?|apps?)\b`,
    "g",
  ),
  // "ai prompt", "text-to-image"
  /\bai\s+prompts?\b|\btext[\s-]to[\s-]image\b/g,
  // Named AI image tools.
  /\bmidjourney\b/g,
  /\bstable[\s-]?diffusion\b/g,
  /\bdall[\s·-]?e\b/g,
  /\badobe\s+firefly\b|\bfirefly\s+ai\b/g,
  /\bleonardo\s+ai\b/g,
  /\bnightcafe\b/g,
];

// Words that cancel a match when they appear shortly before it in the same sentence:
// negations ("not ai generated") and contrasts ("unlike ai art, I paint by hand").
export const NEGATION_BEFORE =
  /\b(?:no|not|never|without|zero|nor|non|isn'?t|aren'?t|wasn'?t|don'?t|doesn'?t|didn'?t|free of|unlike|instead of|rather than|opposed to|versus|vs|against|anti|tired of|beware(?: of)?|hate)\b/;

/** How far before a match (in characters) to look for a negation. */
export const NEGATION_WINDOW = 30;

// "ai-free", "ai free"
export const NEGATION_AFTER = /^[\s-]*free\b/;
